import('ajv').then(m => {
  const Ajv = m.default;
  const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  const validate = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']});
  validate({ssn: 123456789});
  console.log(JSON.stringify(validate.errors, null, 2));
})
